<script setup lang="ts">
import { useI18n } from 'vue-i18n'
import type { AlertEvent, Host, HostSnapshot, Summary } from '../types'
import Card from './Card.vue'
const { t } = useI18n()
const { hosts, summary, alerts, pct, diskPct, ago, alertMessage, eventStatus } = defineProps<{ hosts: Host[], summary: Summary, alerts: AlertEvent[], pct: (value: number | undefined) => string, diskPct: (snapshot: HostSnapshot) => number, ago: (value: string | undefined) => string, alertMessage: (value: string) => string, eventStatus: (value: string) => string }>()
const emit = defineEmits<{ (event: 'navigate', view: string): void; (event: 'select-host', host: Host): void; (event: 'update:host-query', value: string): void }>()
</script>
<template>
<section class="stats"><Card as="article" class="stat-card"><span>{{t("服务器总数")}}</span><b>{{summary.hosts}}</b><small>{{t("已纳入监控")}}</small><i>▣</i></Card><Card as="article" class="stat-card"><span>{{t("在线服务器")}}</span><b class="green">{{summary.online}}</b><small>{{summary.hosts?Math.round(summary.online/summary.hosts*100):0}}{{t("% 在线率")}}</small><i>◉</i></Card><Card as="article" class="stat-card"><span>{{t("平均 CPU")}}</span><b>{{pct(summary.avg_cpu)}}</b><small>{{t("在线主机平均值")}}</small><i>⌁</i></Card><Card as="article" class="stat-card"><span>{{t("平均内存")}}</span><b>{{pct(summary.avg_memory)}}</b><small>{{t("在线主机平均值")}}</small><i>▤</i></Card></section><div class="section-head"><div><h2>{{t("服务器状态")}}</h2><p>{{t("最近一次上报的主机指标")}}</p></div><button class="ghost" @click="emit('navigate', 'hosts')">{{t("查看全部服务器 →")}}</button></div><Card class="panel"><div class="panel-head"><b>{{t("已接入主机")}}</b><span>{{hosts.length}} {{t("台设备")}}</span></div><div class="table-wrap"><table><thead><tr><th>{{t("服务器")}}</th><th>{{t("平台")}}</th><th>CPU</th><th>{{t("内存")}}</th><th>{{t("磁盘")}}</th><th>{{t("进程")}}</th><th>{{t("最后上报")}}</th><th>{{t("状态")}}</th></tr></thead><tbody><tr v-for="h in hosts.slice(0,8)" :key="h.agent_id"><td><b>{{h.snapshot.hostname}}</b></td><td>{{h.snapshot.os}} · {{h.snapshot.arch}}</td><td>{{pct(h.snapshot.cpu?.usage_percent)}}</td><td>{{pct(h.snapshot.memory?.usage_percent)}}</td><td>{{pct(diskPct(h.snapshot))}}</td><td>{{h.snapshot.process_count??'—'}}</td><td>{{ago(h.snapshot.collected_at)}}</td><td><span class="badge" :class="h.status">{{h.status==='online'?t("在线"):t("离线")}}</span></td></tr><tr v-if="!hosts.length"><td colspan="8" class="empty">{{t("还没有监控服务器。前往系统设置，按指引添加第一台服务器。")}}</td></tr></tbody></table></div></Card><div class="lower-grid"><Card class="panel"><div class="panel-head"><b>{{t("最近告警")}}</b><button class="ghost" @click="emit('navigate', 'alerts')">{{t("查看全部")}}</button></div><div v-for="a in alerts.slice(0,5)" :key="a.id" class="alert-line"><span class="severity-dot" :class="a.severity"></span><div><b>{{a.rule_name}} · {{a.host}}</b><small>{{alertMessage(a.message)}}</small></div><span class="badge" :class="a.status">{{eventStatus(a.status)}}</span></div><div v-if="!alerts.length" class="empty pad">{{t("暂无告警事件")}}</div></Card><Card class="panel quick"><div class="panel-head"><b>{{t("快速接入")}}</b><span>{{t("Linux 服务器")}}</span></div><p>{{t("先在系统设置中创建接入密钥，再按步骤添加 Linux 服务器。")}}</p><button class="primary" @click="emit('navigate', 'settings')">{{t("添加 Linux 服务器 →")}}</button></Card></div>
</template>
